"""Contracts to C# records (design spec 7.3), generated by code, never by a model.

``xsd_to_records`` walks an XSD (or the schemas embedded in a WSDL) with lxml; complex types and
global elements become ``public sealed record`` types with ``init`` properties (``required`` for
required elements), ``[JsonPropertyName("camelCase")]`` and ``[TibcoPath("/Root/field")]`` for
lineage. Enumerations become C# enums, repeating elements ``IReadOnlyList<T>``, optional elements
nullable types. ``json_schema_to_records`` does the same for JSON Schema and Swagger 2.0
``definitions`` (the BW6 service descriptors).

The ``TibcoPathAttribute`` class itself is emitted once by the solution generator (Task 14) into
``Contracts/TibcoPathAttribute.cs`` in the same namespace; here only its usage is emitted.

Lineage path: the element path from the first global element (document order, depth first) that
reaches the type; a type no element reaches is rooted at its own name.
"""
from __future__ import annotations

import json
import re
from dataclasses import dataclass, field
from typing import Any

from lxml import etree

from engine.ir.models import Contract

XS = "http://www.w3.org/2001/XMLSchema"

_XS_TYPES: dict[str, str] = {
    "string": "string", "normalizedString": "string", "token": "string", "anyURI": "string",
    "QName": "string", "NCName": "string", "Name": "string", "ID": "string", "IDREF": "string",
    "NMTOKEN": "string", "language": "string", "duration": "string", "gYear": "string",
    "gYearMonth": "string", "gMonthDay": "string", "gDay": "string", "gMonth": "string",
    "int": "int", "integer": "int", "short": "int", "byte": "int", "unsignedShort": "int",
    "unsignedByte": "int", "nonNegativeInteger": "int", "positiveInteger": "int",
    "negativeInteger": "int", "nonPositiveInteger": "int",
    "long": "long", "unsignedInt": "long", "unsignedLong": "ulong",
    "decimal": "decimal", "double": "double", "float": "float", "boolean": "bool",
    "date": "DateOnly", "dateTime": "DateTimeOffset", "time": "TimeOnly",
    "base64Binary": "byte[]", "hexBinary": "byte[]", "anyType": "object", "anySimpleType": "string",
}

_UNBOUNDED = 10**9


# --------------------------------------------------------------------- naming
def _tokens(name: str) -> list[str]:
    return [t for t in re.split(r"[^0-9A-Za-z]+", name) if t]


def pascal(name: str) -> str:
    """``dealerId`` -> ``DealerId``, ``ON-HOLD`` -> ``OnHold``, ``GMF.DB.URL`` -> ``GmfDbUrl``."""
    out = []
    for t in _tokens(name):
        if t.isupper() and len(t) > 1:
            out.append(t[0] + t[1:].lower())
        else:
            out.append(t[0].upper() + t[1:])
    return "".join(out)


def _camel(name: str) -> str:
    return name[:1].lower() + name[1:] if name else name


def _ident(name: str, fallback: str = "Value") -> str:
    p = pascal(name)
    if not p:
        return fallback
    return f"{fallback}{p}" if p[0].isdigit() else p


def _xml_escape(text: str) -> str:
    return " ".join(text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").split())


def _cs_string(text: str) -> str:
    return text.replace("\\", "\\\\").replace('"', '\\"')


# ---------------------------------------------------------------------- model
@dataclass
class _Prop:
    wire_name: str  # the name on the wire (JSON property name)
    cs_name: str
    cs_type: str  # item type, without list or nullable decoration
    required: bool
    repeated: bool
    path_part: str  # "name", "@name", or "" for simple content
    child: str | None = None  # record name when the type is a record


@dataclass
class _Record:
    name: str
    doc: str | None = None
    props: list[_Prop] = field(default_factory=list)


@dataclass
class _Enum:
    name: str
    values: list[str]


class _Model:
    def __init__(self, reserved: frozenset[str] = frozenset(), suffix: str = "") -> None:
        self.records: dict[str, _Record] = {}
        self.enums: dict[str, _Enum] = {}
        self.taken: set[str] = set()
        self.reserved = reserved  # names another contract of the same namespace already emits
        self.suffix = suffix  # appended to a name that is reserved
        self.root_paths: list[tuple[str, str]] = []  # (record, "/Root") in document order

    def _free(self, cand: str) -> bool:
        return bool(cand) and cand not in self.taken and cand not in self.reserved

    def claim(self, preferred: str, alt: str) -> str:
        cands = [preferred]
        if preferred in self.reserved and self.suffix:
            cands.append(preferred + self.suffix)
        cands += [alt, alt + self.suffix] if self.suffix else [alt]
        for cand in cands:
            if self._free(cand):
                self.taken.add(cand)
                return cand
        n = 2
        while not self._free(f"{alt}{n}"):
            n += 1
        self.taken.add(f"{alt}{n}")
        return f"{alt}{n}"

    def finish_props(self, rec: _Record) -> None:
        seen: dict[str, int] = {}
        for p in rec.props:
            if p.cs_name == rec.name:
                p.cs_name = f"{p.cs_name}Value"
            if p.cs_name in seen:
                seen[p.cs_name] += 1
                p.cs_name = f"{p.cs_name}{seen[p.cs_name]}"
            else:
                seen[p.cs_name] = 1

    def names(self) -> list[str]:
        return list(self.records) + list(self.enums)

    def paths(self) -> dict[str, str]:
        out: dict[str, str] = {}

        def walk(rec_name: str, path: str) -> None:
            if rec_name in out or rec_name not in self.records:
                return
            out[rec_name] = path
            for p in self.records[rec_name].props:
                if p.child:
                    walk(p.child, f"{path}/{p.path_part}" if p.path_part else path)

        for rec_name, path in self.root_paths:
            walk(rec_name, path)
        for rec_name in self.records:
            walk(rec_name, f"/{rec_name}")
        return out

    def render(self, namespace: str, source: str) -> str:
        paths = self.paths()
        lines = [
            "// <auto-generated>",
            f"//   Generated by ExiQO Migrate from {source}. Do not edit by hand.",
            "// </auto-generated>",
            "#nullable enable",
            "",
            "using System;",
            "using System.Collections.Generic;",
            "using System.Text.Json.Serialization;",
            "",
            f"namespace {namespace};",
        ]
        for rec in self.records.values():
            base = paths.get(rec.name, f"/{rec.name}")
            lines.append("")
            summary = f"Contract {rec.name} from {source}." + (f" {rec.doc}" if rec.doc else "")
            lines.append(f"/// <summary>{_xml_escape(summary)}</summary>")
            lines.append(f"public sealed record {rec.name}")
            lines.append("{")
            for i, p in enumerate(rec.props):
                if i:
                    lines.append("")
                cs_type = f"IReadOnlyList<{p.cs_type}>" if p.repeated else p.cs_type
                if not p.required:
                    cs_type += "?"
                path = f"{base}/{p.path_part}" if p.path_part else base
                lines.append(f'    [JsonPropertyName("{_cs_string(p.wire_name)}")]')
                lines.append(f'    [TibcoPath("{_cs_string(path)}")]')
                req = "required " if p.required else ""
                lines.append(f"    public {req}{cs_type} {p.cs_name} {{ get; init; }}")
            lines.append("}")
        for en in self.enums.values():
            lines.append("")
            lines.append(f"/// <summary>Enumeration {en.name} from {_xml_escape(source)}.</summary>")
            lines.append(f"[JsonConverter(typeof(JsonStringEnumConverter<{en.name}>))]")
            lines.append(f"public enum {en.name}")
            lines.append("{")
            used: set[str] = set()
            for v in en.values:
                member = _ident(v) if v else "Empty"
                cand, n = member, 2
                while cand in used:
                    cand, n = f"{member}{n}", n + 1
                used.add(cand)
                lines.append(f'    [JsonStringEnumMemberName("{_cs_string(v)}")]')
                lines.append(f"    {cand},")
            lines.append("}")
        return "\n".join(lines) + "\n"


# ------------------------------------------------------------------------ XSD
def _local(tag: Any) -> str:
    return tag.rsplit("}", 1)[-1] if isinstance(tag, str) else ""


def _xs_children(el, *names: str):
    return [c for c in el if isinstance(c.tag, str) and c.tag.startswith(f"{{{XS}}}")
            and (not names or _local(c.tag) in names)]


def _occurs(el, attr: str, default: int) -> int:
    v = el.get(attr)
    if v is None:
        return default
    if v == "unbounded":
        return _UNBOUNDED
    try:
        return int(v)
    except ValueError:
        return default


def _doc(el) -> str | None:
    for ann in _xs_children(el, "annotation"):
        for d in _xs_children(ann, "documentation"):
            text = "".join(d.itertext()).strip()
            if text:
                return text
    return None


class _XsdBuilder:
    def __init__(self, schemas: list[Any], model: _Model) -> None:
        self.m = model
        self.cts: dict[str, Any] = {}
        self.sts: dict[str, Any] = {}
        self.elements: dict[str, Any] = {}
        self.global_order: list[Any] = []
        self.ct_records: dict[str, str] = {}  # complexType name -> record name
        self.el_types: dict[str, tuple[str, str | None]] = {}  # global element -> (C# type, record)
        self.st_enums: dict[str, str] = {}
        for schema in schemas:
            for c in _xs_children(schema):
                name = c.get("name")
                kind = _local(c.tag)
                if not name:
                    continue
                if kind == "complexType":
                    self.cts.setdefault(name, c)
                elif kind == "simpleType":
                    self.sts.setdefault(name, c)
                elif kind == "element":
                    self.elements.setdefault(name, c)
                    self.global_order.append(c)

    # -- qname resolution
    @staticmethod
    def _resolve(el, qname: str | None) -> tuple[str | None, str]:
        if not qname:
            return None, ""
        if ":" in qname:
            prefix, local = qname.split(":", 1)
            return el.nsmap.get(prefix), local
        return el.nsmap.get(None), qname

    def _type_ref(self, el, qname: str, owner: str) -> tuple[str, str | None]:
        """C# type and (record name or None) for a type QName."""
        ns, local = self._resolve(el, qname)
        if ns == XS:
            return _XS_TYPES.get(local, "string"), None
        if local in self.cts:
            name = self._named_ct(local)
            return name, name
        if local in self.sts:
            return self._named_st(local), None
        return ("object", None)  # imported or unknown type

    # -- simple types
    def _enum_values(self, st) -> list[str] | None:
        for r in _xs_children(st, "restriction"):
            vals = [e.get("value", "") for e in _xs_children(r, "enumeration")]
            if vals:
                return vals
        return None

    def _simple_base(self, st) -> str:
        for r in _xs_children(st, "restriction"):
            if r.get("base"):
                cs, _ = self._type_ref(r, r.get("base"), "")
                return cs
            for inner in _xs_children(r, "simpleType"):
                return self._simple_base(inner)
        return "string"

    def _named_st(self, name: str) -> str:
        if name in self.st_enums:
            return self.st_enums[name]
        st = self.sts[name]
        vals = self._enum_values(st)
        if vals is None:
            cs = self._simple_base(st)
            self.st_enums[name] = cs
            return cs
        en = self.m.claim(_ident(name), _ident(name) + "Enum")
        self.st_enums[name] = en
        self.m.enums[en] = _Enum(en, vals)
        return en

    def _inline_st(self, st, elem_name: str, owner: str) -> str:
        vals = self._enum_values(st)
        if vals is None:
            return self._simple_base(st)
        en = self.m.claim(_ident(elem_name), owner + _ident(elem_name))
        self.m.enums[en] = _Enum(en, vals)
        return en

    # -- complex types
    def _named_ct(self, name: str) -> str:
        if name in self.ct_records:
            return self.ct_records[name]
        rec_name = self.m.claim(_ident(name), _ident(name) + "Type")
        self.ct_records[name] = rec_name
        ct = self.cts[name]
        rec = _Record(rec_name, _doc(ct))
        self.m.records[rec_name] = rec
        rec.props = self._ct_props(ct, rec_name, set())
        self.m.finish_props(rec)
        return rec_name

    def _inline_ct(self, ct, elem_name: str, owner: str, doc: str | None, memo_key: str | None = None) -> str:
        rec_name = self.m.claim(_ident(elem_name), owner + _ident(elem_name))
        if memo_key is not None:  # registered before the walk so a recursive ref finds it
            self.el_types[memo_key] = (rec_name, rec_name)
        rec = _Record(rec_name, doc or _doc(ct))
        self.m.records[rec_name] = rec
        rec.props = self._ct_props(ct, rec_name, set())
        self.m.finish_props(rec)
        return rec_name

    def _ct_props(self, ct, owner: str, seen_bases: set[str]) -> list[_Prop]:
        props: list[_Prop] = []
        for c in _xs_children(ct):
            kind = _local(c.tag)
            if kind in ("sequence", "all", "choice"):
                props += self._particle(c, owner, kind == "choice", False)
            elif kind == "attribute":
                props += self._attribute(c, owner)
            elif kind in ("complexContent", "simpleContent"):
                for d in _xs_children(c, "extension", "restriction"):
                    base = d.get("base")
                    if _local(d.tag) == "extension" and base:
                        ns, local = self._resolve(d, base)
                        if ns != XS and local in self.cts and local not in seen_bases:
                            props += self._ct_props(self.cts[local], owner, seen_bases | {local})
                        elif kind == "simpleContent":
                            cs, _ = self._type_ref(d, base, owner)
                            props.append(_Prop("value", "Value", cs, True, False, ""))
                    elif kind == "simpleContent" and base:
                        cs, _ = self._type_ref(d, base, owner)
                        props.append(_Prop("value", "Value", cs, True, False, ""))
                    props += self._ct_props(d, owner, seen_bases)
        return props

    def _particle(self, comp, owner: str, optional: bool, repeated: bool) -> list[_Prop]:
        optional = optional or _occurs(comp, "minOccurs", 1) == 0
        repeated = repeated or _occurs(comp, "maxOccurs", 1) > 1
        props: list[_Prop] = []
        for c in _xs_children(comp):
            kind = _local(c.tag)
            if kind == "element":
                props.append(self._element(c, owner, optional, repeated))
            elif kind in ("sequence", "all"):
                props += self._particle(c, owner, optional, repeated)
            elif kind == "choice":
                props += self._particle(c, owner, True, repeated)
        return props

    def _element(self, el, owner: str, optional: bool, repeated: bool) -> _Prop:
        min_o = _occurs(el, "minOccurs", 1)
        max_o = _occurs(el, "maxOccurs", 1)
        required = not optional and min_o >= 1 and el.get("nillable") != "true"
        repeated = repeated or max_o > 1
        target = el
        name = el.get("name") or ""
        if el.get("ref"):
            _, local = self._resolve(el, el.get("ref"))
            name = local
            target = self.elements.get(local, el)
        cs, child = self._element_type(target, name, owner)
        return _Prop(_camel(name), _ident(name), cs, required, repeated, name, child)

    def _element_type(self, el, name: str, owner: str) -> tuple[str, str | None]:
        parent = el.getparent()
        is_global = parent is not None and _local(parent.tag) == "schema" and bool(el.get("name"))
        key = el.get("name") if is_global else None
        if key is not None and key in self.el_types:  # a global element has one type, however referenced
            return self.el_types[key]
        if el.get("type"):
            out = self._type_ref(el, el.get("type"), owner)
        elif _xs_children(el, "complexType"):
            rec = self._inline_ct(_xs_children(el, "complexType")[0], name, owner, _doc(el), key)
            out = (rec, rec)
        elif _xs_children(el, "simpleType"):
            out = (self._inline_st(_xs_children(el, "simpleType")[0], name, owner), None)
        else:
            out = ("object", None)
        if key is not None:
            self.el_types[key] = out
        return out

    def _attribute(self, at, owner: str) -> list[_Prop]:
        name = at.get("name")
        if not name and at.get("ref"):
            _, name = self._resolve(at, at.get("ref"))
        if not name:
            return []
        if at.get("type"):
            cs, _ = self._type_ref(at, at.get("type"), owner)
        else:
            sts = _xs_children(at, "simpleType")
            cs = self._inline_st(sts[0], name, owner) if sts else "string"
        return [_Prop(_camel(name), _ident(name), cs, at.get("use") == "required", False, f"@{name}")]

    def build(self) -> _Model:
        for el in self.global_order:
            name = el.get("name")
            _, rec = self._element_type(el, name, "")
            if rec:
                self.m.root_paths.append((rec, f"/{name}"))
        for name in self.cts:
            self._named_ct(name)
        for name in self.sts:
            self._named_st(name)
        return self.m


_PARSER = etree.XMLParser(resolve_entities=False, no_network=True, remove_comments=True, huge_tree=False)


def _schemas(contract: Contract) -> list[Any]:
    root = etree.fromstring(contract.text.encode("utf-8"), _PARSER)
    if root.tag == f"{{{XS}}}schema":
        return [root]
    return [s for s in root.iter(f"{{{XS}}}schema")]  # WSDL types


def _suffix(contract: Contract) -> str:
    """Disambiguating suffix for a record name another contract of the namespace already emits."""
    if contract.kind in ("json", "wsdl"):
        return contract.kind.capitalize()
    return _ident(_stem(contract))


def _stem(contract: Contract) -> str:
    return contract.id.rsplit("/", 1)[-1].rsplit(".", 1)[0].rsplit(".", 1)[-1]


def _xsd_model(contract: Contract, reserved: frozenset[str] = frozenset()) -> _Model:
    return _XsdBuilder(_schemas(contract), _Model(reserved, _suffix(contract))).build()


def xsd_to_records(contract: Contract, namespace: str, reserved: frozenset[str] = frozenset()) -> str:
    """C# records and enums for an XSD (or the schemas inside a WSDL) in ``namespace``.

    ``reserved`` are record names other contracts already emit into the same namespace; a clash is
    renamed with a suffix (see ``plan_contracts``).
    """
    return _xsd_model(contract, reserved).render(namespace, contract.id)


# ----------------------------------------------------------------------- JSON
class _JsonBuilder:
    def __init__(self, doc: dict[str, Any], fallback_name: str, model: _Model) -> None:
        self.m = model
        self.doc = doc
        self.defs: dict[str, Any] = {}
        for key in ("definitions", "$defs"):
            if isinstance(doc.get(key), dict):
                for k, v in doc[key].items():
                    self.defs.setdefault(k, v)
        self.def_records: dict[str, str] = {}
        self.fallback = fallback_name

    def _ref_name(self, ref: str) -> str:
        return ref.rsplit("/", 1)[-1]

    def _refs_in(self, schema: Any) -> set[str]:
        out: set[str] = set()
        if isinstance(schema, dict):
            if isinstance(schema.get("$ref"), str):
                out.add(self._ref_name(schema["$ref"]))
            for v in schema.values():
                out |= self._refs_in(v)
        elif isinstance(schema, list):
            for v in schema:
                out |= self._refs_in(v)
        return out

    def _def_record(self, name: str) -> str | None:
        if name in self.def_records:
            return self.def_records[name]
        schema = self.defs.get(name)
        if not isinstance(schema, dict) or not self._is_object(schema):
            return None
        rec_name = self.m.claim(_ident(name), _ident(name) + "Record")
        self.def_records[name] = rec_name
        self._fill(rec_name, schema)
        return rec_name

    @staticmethod
    def _is_object(schema: dict[str, Any]) -> bool:
        return schema.get("type") == "object" or "properties" in schema or "allOf" in schema

    def _fill(self, rec_name: str, schema: dict[str, Any]) -> None:
        rec = _Record(rec_name, schema.get("description") if isinstance(schema.get("description"), str) else None)
        self.m.records[rec_name] = rec
        rec.props = self._props(schema, rec_name)
        self.m.finish_props(rec)

    def _props(self, schema: dict[str, Any], owner: str) -> list[_Prop]:
        props: list[_Prop] = []
        for part in schema.get("allOf") or []:
            if isinstance(part, dict) and isinstance(part.get("$ref"), str):
                base = self.defs.get(self._ref_name(part["$ref"]))
                if isinstance(base, dict):
                    props += self._props(base, owner)
            elif isinstance(part, dict):
                props += self._props(part, owner)
        required = set(schema.get("required") or [])
        for name, ps in (schema.get("properties") or {}).items():
            cs, child, repeated = self._type(ps if isinstance(ps, dict) else {}, name, owner)
            props.append(_Prop(name, _ident(name), cs, name in required, repeated, name, child))
        return props

    def _type(self, ps: dict[str, Any], name: str, owner: str) -> tuple[str, str | None, bool]:
        if isinstance(ps.get("$ref"), str):
            ref = self._ref_name(ps["$ref"])
            rec = self._def_record(ref)
            if rec:
                return rec, rec, False
            target = self.defs.get(ref)
            return (self._type(target, name, owner)[0] if isinstance(target, dict) else "object"), None, False
        t = ps.get("type")
        if isinstance(t, list):
            t = next((x for x in t if x != "null"), None)
        if t == "array":
            items = ps.get("items") if isinstance(ps.get("items"), dict) else {}
            cs, child, _ = self._type(items, name, owner)
            return cs, child, True
        if ps.get("enum") and t in (None, "string"):
            en = self.m.claim(_ident(name), owner + _ident(name))
            self.m.enums[en] = _Enum(en, [str(v) for v in ps["enum"]])
            return en, None, False
        if t == "string":
            fmt = ps.get("format")
            return {"date": "DateOnly", "date-time": "DateTimeOffset", "byte": "byte[]",
                    "time": "TimeOnly"}.get(fmt, "string"), None, False
        if t == "integer":
            return ("long" if ps.get("format") == "int64" else "int"), None, False
        if t == "number":
            return {"double": "double", "float": "float"}.get(ps.get("format"), "decimal"), None, False
        if t == "boolean":
            return "bool", None, False
        if self._is_object(ps) and ps.get("properties"):
            rec = self.m.claim(_ident(name), owner + _ident(name))
            self._fill(rec, ps)
            return rec, rec, False
        return "object", None, False

    def build(self) -> _Model:
        referenced: set[str] = set()
        for name, schema in self.defs.items():
            referenced |= {r for r in self._refs_in(schema) if r != name}
        if isinstance(self.doc.get("properties"), dict):
            title = self.doc.get("title") if isinstance(self.doc.get("title"), str) else self.fallback
            rec = self.m.claim(_ident(title), _ident(title) + "Record")
            self._fill(rec, self.doc)
            self.m.root_paths.append((rec, f"/{title}"))
        for name in self.defs:
            if name not in referenced:
                rec = self._def_record(name)
                if rec:
                    self.m.root_paths.append((rec, f"/{name}"))
        for name in self.defs:
            self._def_record(name)
        return self.m


def _json_model(contract: Contract, reserved: frozenset[str] = frozenset()) -> _Model:
    doc = json.loads(contract.text) if contract.text.strip() else {}
    if not isinstance(doc, dict):
        doc = {}
    return _JsonBuilder(doc, _stem(contract), _Model(reserved, _suffix(contract))).build()


def json_schema_to_records(contract: Contract, namespace: str, reserved: frozenset[str] = frozenset()) -> str:
    """C# records and enums for a JSON Schema or Swagger 2.0 document (``definitions``/``$defs``)."""
    return _json_model(contract, reserved).render(namespace, contract.id)


# ----------------------------------------------------------------- dispatcher
def _model(contract: Contract, reserved: frozenset[str] = frozenset()) -> _Model:
    return _json_model(contract, reserved) if contract.kind == "json" else _xsd_model(contract, reserved)


def to_records(contract: Contract, namespace: str, reserved: frozenset[str] = frozenset()) -> str:
    """Dispatch on ``contract.kind``: json to ``json_schema_to_records``, xsd and wsdl to XSD."""
    if contract.kind == "json":
        return json_schema_to_records(contract, namespace, reserved)
    return xsd_to_records(contract, namespace, reserved)


def record_names(contract: Contract, reserved: frozenset[str] = frozenset()) -> list[str]:
    """Names of the records then enums ``to_records`` emits, in emission order."""
    try:
        return _model(contract, reserved).names()
    except (etree.XMLSyntaxError, ValueError):
        return []


# ------------------------------------------------------- per-application plan
def contract_module(contract: Contract) -> str:
    """The module (project folder) a contract belongs to: the first segment of its id."""
    return contract.id.split("/", 1)[0] if "/" in contract.id else ""


def contract_namespace(app_name: str, contract: Contract) -> str:
    """``<App>.Core.Contracts.<Module>``; ``TibcoPathAttribute`` in ``<App>.Core.Contracts`` is in scope."""
    module = _ident(contract_module(contract), "Module")
    return f"{app_name}.Core.Contracts.{module}" if contract_module(contract) else f"{app_name}.Core.Contracts"


def contract_file(contract: Contract) -> str:
    """Natural file path in the Core project: ``Contracts/<Module>/<Stem>.cs``."""
    module = contract_module(contract)
    folder = f"Contracts/{_ident(module, 'Module')}" if module else "Contracts"
    return f"{folder}/{_ident(_stem(contract))}.cs"


@dataclass
class ContractPlan:
    contract_id: str
    module: str
    namespace: str
    file: str
    record_names: list[str]
    reserved: frozenset[str]  # pass to ``to_records`` so the rendered names match ``record_names``
    collisions: dict[str, str] = field(default_factory=dict)  # natural name -> emitted name
    collides_with: dict[str, str] = field(default_factory=dict)  # natural name -> contract id owning it


_KIND_RANK = {"xsd": 0, "wsdl": 1, "json": 2}


def plan_contracts(app_name: str, contracts: list[Contract]) -> dict[str, ContractPlan]:
    """Namespace, file and record names for every contract of one application.

    Within a module (one namespace) contracts are taken XSD first, then WSDL, then JSON, each by id;
    a record name an earlier contract already emits is renamed with a suffix (``Json``, ``Wsdl``, or
    the XSD stem). Two contracts never share a file path.
    """
    plans: dict[str, ContractPlan] = {}
    owners: dict[str, dict[str, str]] = {}  # namespace -> record name -> contract id
    files: set[str] = set()
    for c in sorted(contracts, key=lambda c: (contract_module(c), _KIND_RANK.get(c.kind, 9), c.id)):
        ns = contract_namespace(app_name, c)
        owned = owners.setdefault(ns, {})
        reserved = frozenset(owned)
        natural = record_names(c)
        names = record_names(c, reserved)
        collisions = {n: e for n, e in zip(natural, names, strict=False) if n in reserved and n != e}
        file = contract_file(c)
        if file in files:
            base = file[: -len(".cs")]
            file, n = f"{base}{_suffix(c)}.cs", 2
            while file in files:
                file, n = f"{base}{_suffix(c)}{n}.cs", n + 1
        files.add(file)
        plans[c.id] = ContractPlan(
            contract_id=c.id, module=contract_module(c), namespace=ns, file=file, record_names=names,
            reserved=reserved, collisions=collisions,
            collides_with={n: owned[n] for n in collisions})
        for n in names:
            owned.setdefault(n, c.id)
    return plans
